+bool InternalValue::isSelectable() const {
+    UErrorCode localStatus = U_ZERO_ERROR;
+    const FunctionValue* val = getValue(localStatus);
+    if (U_FAILURE(localStatus)) {
+        return false;
+    }
+    return val->isSelectable();
+}
