+        || s == options::MINIMUM_FRACTION_DIGITS
+        || s == options::MAXIMUM_FRACTION_DIGITS
+        || s == options::MINIMUM_SIGNIFICANT_DIGITS
+        || s == options::MAXIMUM_SIGNIFICANT_DIGITS
