+    }
+    if (increment != 1) {
+        hasIncrement = true;
+    }
+    // Divide by 100 to get cents-based rounding
+    double incrementToUse = U_SUCCESS(localStatus) ? increment / 100.0 : 0.01;
+    return Precision::increment(incrementToUse).withMinFraction(minFractionDigits);
+}
